"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[5894],{6042:n=>{n.exports=JSON.parse('{"blogPosts":[{"id":"loon4mac-tcp-performance","metadata":{"permalink":"/blog/loon4mac-tcp-performance","source":"@site/blog/2026-10-20-loon4mac-tcp-performance/index.md","title":"Loon4Mac build 1007\uff1aM1 Max TCP \u6027\u80fd\u6d4b\u8bd5","description":"Loon4Mac build 1007 \u5728 Apple M1 Max \u4e0a\u7684\u672c\u5730 TCP \u6027\u80fd\uff0c\u4ee5\u53ca\u81ea\u52a8\u548c\u624b\u52a8\u6d4b\u8bd5\u65b9\u6cd5\u3002","date":"2026-10-20T00:00:00.000Z","formattedDate":"2026\u5e7410\u670820\u65e5","tags":[{"label":"Loon4Mac","permalink":"/blog/tags/loon-4-mac"},{"label":"\u6027\u80fd\u6d4b\u8bd5","permalink":"/blog/tags/\u6027\u80fd\u6d4b\u8bd5"},{"label":"macOS","permalink":"/blog/tags/mac-os"}],"readingTime":2.575,"hasTruncateMarker":true,"authors":[{"name":"Loon0x00","title":"Maintainer of Loon","url":"https://github.com/Loon0x00","imageURL":"https://github.com/Loon0x00.png","key":"loon"}],"frontMatter":{"slug":"loon4mac-tcp-performance","title":"Loon4Mac build 1007\uff1aM1 Max TCP \u6027\u80fd\u6d4b\u8bd5","description":"Loon4Mac build 1007 \u5728 Apple M1 Max \u4e0a\u7684\u672c\u5730 TCP \u6027\u80fd\uff0c\u4ee5\u53ca\u81ea\u52a8\u548c\u624b\u52a8\u6d4b\u8bd5\u65b9\u6cd5\u3002","authors":["loon"],"tags":["Loon4Mac","\u6027\u80fd\u6d4b\u8bd5","macOS"]},"unlisted":false,"nextItem":{"title":"Welcome","permalink":"/blog/welcome"}},"content":"\u5373\u5c06\u53d1\u5e03\u7684 Loon4Mac build 1007 \u5bf9 TCP \u8f6c\u53d1\u6027\u80fd\u8fdb\u884c\u4e86\u4f18\u5316\u3002\u5728 Apple M1 Max \u4e0a\uff0c\u5355\u6d41\u4e0a\u4f20\u8fbe\u5230 **12.25 Gbps**\uff0c\u5355\u6d41\u4e0b\u8f7d\u8fbe\u5230 **13.97 Gbps**\uff0c\u56db\u6d41\u4e0b\u8f7d\u5408\u8ba1\u8fbe\u5230 **20.61 Gbps**\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u6d4b\u8bd5\u7ed3\u679c\\n\\n### \u6d4b\u8bd5\u73af\u5883\\n\\n| \u9879\u76ee | \u914d\u7f6e |\\n| --- | --- |\\n| \u8bbe\u5907 | Apple M1 Max\uff0c32 GB \u5185\u5b58 |\\n| \u7cfb\u7edf | macOS 27.2 |\\n| Loon | Loon4Mac build 1007 |\\n| \u6d4b\u8bd5\u5de5\u5177 | Apple iperf3-darwin 3.8.1 |\\n| TUN MTU | 4000 |\\n\\n\u6d4b\u8bd5\u6d41\u91cf\u4ece\u672c\u673a\u53d1\u51fa\uff0c\u7ecf Loon \u7684 TUN \u548c TCP \u6808\u8f6c\u53d1\u5230\u672c\u673a iperf3 \u670d\u52a1\u7aef\u3002\u6bcf\u9879\u9884\u70ed 2 \u79d2\u3001\u6d4b\u8bd5 10 \u79d2\uff0c\u5404\u6267\u884c\u4e00\u6b21\u3002\\n\\n| \u6d4b\u8bd5\u9879\u76ee | TCP \u901f\u5ea6 | Loon NE RSS \u5cf0\u503c |\\n| --- | ---: | ---: |\\n| \u5355\u6d41\u4e0a\u4f20 | **12.25 Gbps** | 55.70 MiB |\\n| \u5355\u6d41\u4e0b\u8f7d | **13.97 Gbps** | 59.28 MiB |\\n| \u56db\u6d41\u4e0a\u4f20\uff08\u5408\u8ba1\uff09 | **10.67 Gbps** | 60.55 MiB |\\n| \u56db\u6d41\u4e0b\u8f7d\uff08\u5408\u8ba1\uff09 | **20.61 Gbps** | 90.23 MiB |\\n\\n\u6d4b\u8bd5\u524d Loon NE \u7684\u7a7a\u8f7d RSS \u7ea6\u4e3a 46.45 MiB\u3002\u56db\u6d41\u7ed3\u679c\u662f\u56db\u6761 TCP \u8fde\u63a5\u7684\u5408\u8ba1\u901f\u5ea6\uff1bRSS \u662f\u6574\u4e2a Loon \u7f51\u7edc\u6269\u5c55\u8fdb\u7a0b\u7684\u5185\u5b58\uff0c\u4e0d\u662f\u5355\u6761\u8fde\u63a5\u5360\u7528\u3002\\n\\n## \u6d4b\u8bd5\u65b9\u6cd5\\n\\n### Loon \u914d\u7f6e\\n\\n\u5c06\u4ee5\u4e0b\u5185\u5bb9\u5408\u5e76\u5230\u73b0\u6709\u914d\u7f6e\uff0c`DOMAIN` \u89c4\u5219\u9700\u8981\u653e\u5728 `FINAL` \u4e4b\u524d\uff1a\\n\\n```ini\\n[Host]\\nbench.loon.test = 127.0.0.1\\n\\n[Rule]\\nDOMAIN,bench.loon.test,DIRECT\\n```\\n\\n\u4fdd\u5b58\u914d\u7f6e\u5e76\u8fde\u63a5 Loon\u3002`bench.loon.test` \u4e0d\u8981\u52a0\u5165 `real-ip`\uff0c\u4e5f\u4e0d\u8981\u5199\u5165\u7cfb\u7edf `/etc/hosts`\u3002\\n\\n### \u81ea\u52a8\u6d4b\u8bd5\u811a\u672c\\n\\n[\u4e0b\u8f7d Loon4Mac TCP \u6d4b\u8bd5\u811a\u672c\uff08\u5360\u4f4d\u94fe\u63a5\uff09](https://example.com/loon4mac-tcp-test.sh)\\n\\n\u811a\u672c\u4f1a\u4f9d\u6b21\u6d4b\u8bd5\u5355\u6d41\u4e0a\u4f20\u3001\u5355\u6d41\u4e0b\u8f7d\u3001\u56db\u6d41\u4e0a\u4f20\u548c\u56db\u6d41\u4e0b\u8f7d\uff0c\u5e76\u8bb0\u5f55 Loon NE \u7684 RSS\u3002\\n\\n### \u624b\u52a8\u6d4b\u8bd5\\n\\n\u5148\u5728\u4e00\u4e2a\u7ec8\u7aef\u542f\u52a8\u670d\u52a1\u7aef\uff1a\\n\\n```bash\\n/usr/bin/arch -arm64 /usr/bin/iperf3-darwin -s -B 127.0.0.1 -p 5201\\n```\\n\\n\u5728\u53e6\u4e00\u4e2a\u7ec8\u7aef\u4f9d\u6b21\u6267\u884c\uff1a\\n\\n```bash\\n# \u5355\u6d41\u4e0a\u4f20\\n/usr/bin/arch -arm64 /usr/bin/iperf3-darwin -c bench.loon.test -4 -p 5201 -O 2 -t 10 -i 1\\n\\n# \u5355\u6d41\u4e0b\u8f7d\\n/usr/bin/arch -arm64 /usr/bin/iperf3-darwin -c bench.loon.test -4 -p 5201 -O 2 -t 10 -i 1 -R\\n\\n# \u56db\u6d41\u4e0a\u4f20\\n/usr/bin/arch -arm64 /usr/bin/iperf3-darwin -c bench.loon.test -4 -p 5201 -O 2 -t 10 -i 1 -P 4\\n\\n# \u56db\u6d41\u4e0b\u8f7d\\n/usr/bin/arch -arm64 /usr/bin/iperf3-darwin -c bench.loon.test -4 -p 5201 -O 2 -t 10 -i 1 -P 4 -R\\n```\\n\\n\u5355\u6d41\u67e5\u770b\u6700\u7ec8\u7684 `receiver`\uff0c\u56db\u6d41\u67e5\u770b `[SUM] receiver`\u3002\u5ba2\u6237\u7aef\u5fc5\u987b\u8fde\u63a5 `bench.loon.test`\uff0c\u5982\u679c\u76f4\u63a5\u8fde\u63a5 `127.0.0.1`\uff0c\u6d41\u91cf\u4e0d\u4f1a\u7ecf\u8fc7 Loon\u3002"},{"id":"welcome","metadata":{"permalink":"/blog/welcome","source":"@site/blog/2024-03-15-welcome/index.md","title":"Welcome","description":"\u6b22\u8fce\u6765\u5230Loon\u57fa\u5730\uff0c\u8fd9\u91cc\u5c06\u4f1a\u53d1\u5e03Loon\u7684\u4f7f\u7528\u6559\u7a0b\u3001app\u516c\u544a\u3001\u91cd\u8981\u7248\u672c\u66f4\u65b0\u65e5\u5fd7\u7b49\u3002","date":"2024-03-15T00:00:00.000Z","formattedDate":"2024\u5e743\u670815\u65e5","tags":[{"label":"hello","permalink":"/blog/tags/hello"}],"readingTime":0.155,"hasTruncateMarker":false,"authors":[{"name":"Loon0x00","title":"Maintainer of Loon","url":"https://github.com/Loon0x00","imageURL":"https://github.com/Loon0x00.png","key":"loon"}],"frontMatter":{"slug":"welcome","title":"Welcome","authors":["loon"],"tags":["hello"]},"unlisted":false,"prevItem":{"title":"Loon4Mac build 1007\uff1aM1 Max TCP \u6027\u80fd\u6d4b\u8bd5","permalink":"/blog/loon4mac-tcp-performance"}},"content":"\u6b22\u8fce\u6765\u5230Loon\u57fa\u5730\uff0c\u8fd9\u91cc\u5c06\u4f1a\u53d1\u5e03Loon\u7684\u4f7f\u7528\u6559\u7a0b\u3001app\u516c\u544a\u3001\u91cd\u8981\u7248\u672c\u66f4\u65b0\u65e5\u5fd7\u7b49\u3002"}]}')}}]);